export interface ConnectorConfig {
  /** Salesforce instance host, e.g. "na34.salesforce.com" or "mycompany.my.salesforce.com" */
  salesforceInstance: string;
  /** Salesforce REST API version, e.g. "v68.0" */
  salesforceApiVersion: string;
  /** OAuth 2.0 bearer token for Salesforce API authentication */
  salesforceAccessToken: string;
  /** Injected fetch implementation for testing; defaults to global fetch */
  fetch?: typeof fetch;
}

export interface HubSpotDealWebhookPayload {
  id: string;
  properties: {
    dealname: string;
    amount: string;
    dealstage: string;
    domain: string;
    company_name: string;
  };
}

export interface HandleResult {
  salesforceAccountId: string;
  success: boolean;
  errors: string[];
  upserted: boolean;
}

function validatePayload(payload: unknown): HubSpotDealWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object');
  }
  const p = payload as Record<string, unknown>;
  if (typeof p.id !== 'string' || !p.id) {
    throw new Error('Missing required field: id');
  }
  if (!p.properties || typeof p.properties !== 'object') {
    throw new Error('Missing required field: properties');
  }
  const props = p.properties as Record<string, unknown>;
  const requiredProps = ['company_name', 'domain', 'amount', 'dealstage'] as const;
  for (const key of requiredProps) {
    if (typeof props[key] !== 'string' || !props[key]) {
      throw new Error(`Missing required field: properties.${key}`);
    }
  }
  return payload as HubSpotDealWebhookPayload;
}

function buildSalesforceUrl(config: ConnectorConfig, domain: string): string {
  const encodedDomain = encodeURIComponent(domain);
  return `https://${config.salesforceInstance}/services/data/${config.salesforceApiVersion}/sobjects/Account/Website/${encodedDomain}`;
}

function buildRequestBody(payload: HubSpotDealWebhookPayload): Record<string, unknown> {
  return {
    Name: payload.properties.company_name,
    Website: payload.properties.domain,
    Annual_Revenue__c: parseFloat(payload.properties.amount),
    StageName: payload.properties.dealstage,
    external_id__c: payload.id,
  };
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  const validated = validatePayload(payload);
  const fetchImpl = config.fetch ?? fetch;

  const url = buildSalesforceUrl(config, validated.properties.domain);
  const body = buildRequestBody(validated);

  const response = await fetchImpl(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${config.salesforceAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const text = await response.text().catch(() => '');
    throw new Error(
      `Salesforce upsert failed: ${response.status} ${response.statusText} at ${url} - ${text}`
    );
  }

  const result = (await response.json()) as {
    id: string;
    success: boolean;
    errors: string[];
  };

  return {
    salesforceAccountId: result.id,
    success: result.success,
    errors: result.errors ?? [],
    upserted: true,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, HubSpotDealWebhookPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      salesforceInstance: 'na34.salesforce.com',
      salesforceApiVersion: 'v68.0',
      salesforceAccessToken: 'test-access-token',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.salesforceAccountId).toBe('001xx000003DGhpAAG');
    expect(result.success).toBe(true);
    expect(result.upserted).toBe(true);
  });
});

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    salesforceInstance: 'na34.salesforce.com',
    salesforceApiVersion: 'v68.0',
    salesforceAccessToken: 'test-access-token',
  };

  it('happy path: upserts Account by Website domain with correct field mapping', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.includes('/sobjects/Account/Website/acme.com')
        ? jsonResponse({ id: '001xx000003DGhpAAG', success: true, errors: [] }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    );

    const payload: HubSpotDealWebhookPayload = {
      id: '12345',
      properties: {
        dealname: 'Acme Corp Deal',
        amount: '50000',
        dealstage: 'qualifiedtobuy',
        domain: 'acme.com',
        company_name: 'Acme Corporation',
      },
    };

    const result = await handle(payload, { ...baseConfig, fetch });

    expect(calls).toHaveLength(1);
    const call = calls[0];
    expect(call.method).toBe('PATCH');
    expect(call.url).toBe('https://na34.salesforce.com/services/data/v68.0/sobjects/Account/Website/acme.com');
    expect(call.headers.get('authorization')).toBe('Bearer test-access-token');
    expect(call.json).toEqual({
      Name: 'Acme Corporation',
      Website: 'acme.com',
      Annual_Revenue__c: 50000,
      StageName: 'qualifiedtobuy',
      external_id__c: '12345',
    });
    expect(result.salesforceAccountId).toBe('001xx000003DGhpAAG');
    expect(result.success).toBe(true);
    expect(result.upserted).toBe(true);
  });

  it('uses Bearer authentication from config', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      jsonResponse({ id: '001xx000003DGhpAAG', success: true, errors: [] }, 200)
    );

    const payload: HubSpotDealWebhookPayload = {
      id: '12345',
      properties: {
        dealname: 'Test Deal',
        amount: '10000',
        dealstage: 'prospecting',
        domain: 'test.com',
        company_name: 'Test Company',
      },
    };

    await handle(payload, { ...baseConfig, salesforceAccessToken: 'custom-token-123', fetch });

    expect(calls[0].headers.get('authorization')).toBe('Bearer custom-token-123');
  });

  it('maps all fields correctly including numeric Annual_Revenue__c', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      jsonResponse({ id: '001xx000003DGhpAAG', success: true, errors: [] }, 200)
    );

    const payload: HubSpotDealWebhookPayload = {
      id: '999',
      properties: {
        dealname: 'Big Deal',
        amount: '123456.78',
        dealstage: 'closedwon',
        domain: 'bigcorp.io',
        company_name: 'Big Corp Inc',
      },
    };

    await handle(payload, { ...baseConfig, fetch });

    expect(calls[0].json).toEqual({
      Name: 'Big Corp Inc',
      Website: 'bigcorp.io',
      Annual_Revenue__c: 123456.78,
      StageName: 'closedwon',
      external_id__c: '999',
    });
  });

  it('throws descriptive error when required field id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      properties: {
        dealname: 'Test',
        amount: '100',
        dealstage: 'prospecting',
        domain: 'test.com',
        company_name: 'Test Co',
      },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: id');
  });

  it('throws descriptive error when required property company_name is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      id: '123',
      properties: {
        dealname: 'Test',
        amount: '100',
        dealstage: 'prospecting',
        domain: 'test.com',
      },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: properties.company_name'
    );
  });

  it('throws descriptive error when required property domain is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      id: '123',
      properties: {
        dealname: 'Test',
        amount: '100',
        dealstage: 'prospecting',
        company_name: 'Test Co',
      },
