    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: properties.domain'
    );
  });

  it('throws descriptive error when required property amount is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      id: '123',
      properties: {
        dealname: 'Test',
        dealstage: 'prospecting',
        domain: 'test.com',
        company_name: 'Test Co',
      },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: properties.amount'
    );
  });

  it('throws descriptive error when required property dealstage is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      id: '123',
      properties: {
        dealname: 'Test',
        amount: '100',
        domain: 'test.com',
        company_name: 'Test Co',
      },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: properties.dealstage'
    );
  });

  it('throws error with status code and endpoint on non-2xx response', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      jsonResponse({ error: 'Unauthorized' }, 401)
    );

    const payload: HubSpotDealWebhookPayload = {
      id: '12345',
      properties: {
        dealname: 'Test Deal',
        amount: '10000',
        dealstage: 'prospecting',
        domain: 'test.com',
        company_name: 'Test Company',
      },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Salesforce upsert failed: 401 Unauthorized at https://na34.salesforce.com/services/data/v68.0/sobjects/Account/Website/test.com'
    );
    expect(calls).toHaveLength(1);
  });

  it('throws error with status code and endpoint on 404 response', async () => {
    const { fetch } = fakeFetch((req) =>
      jsonResponse({ error: 'Not Found' }, 404)
    );

    const payload: HubSpotDealWebhookPayload = {
      id: '12345',
      properties: {
        dealname: 'Test Deal',
        amount: '10000',
        dealstage: 'prospecting',
        domain: 'nonexistent.com',
        company_name: 'Test Company',
      },
