    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Salesforce upsert failed: 404 Not Found at https://na34.salesforce.com/services/data/v68.0/sobjects/Account/Website/nonexistent.com'
    );
  });

  it('throws error with status code and endpoint on 500 response', async () => {
    const { fetch } = fakeFetch((req) =>
      jsonResponse({ error: 'Internal Server Error' }, 500)
    );

    const payload: HubSpotDealWebhookPayload = {
      id: '12345',
      properties: {
        dealname: 'Test Deal',
        amount: '10000',
        dealstage: 'prospecting',
        domain: 'error.com',
        company_name: 'Test Company',
      },
